const A='/api/index?action=',S={connected:false,hubs:[],hub:'',projects:[],selected:new Set(),preview:[],results:[],search:''};const $=s=>document.querySelector(s),esc=x=>String(x??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m])),api=async(a,o={})=>{const r=await fetch(A+a,{credentials:'include',headers:{'Content-Type':'application/json'},...o}),d=await r.json().catch(()=>({message:r.statusText}));if(!r.ok)throw new Error(d.message);return d};function table(h,r){return `<div class="table"><table><thead><tr>${h.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${r.length?r.map(x=>`<tr>${x.map(v=>`<td>${v??''}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${h.length}">No projects loaded.</td></tr>`}</tbody></table></div>`}function visible(){const q=S.search.toLowerCase();return S.projects.filter(p=>[p.name,p.jobNumber,p.status,p.id].some(v=>String(v).toLowerCase().includes(q)))}function render(){const pm=new Map(S.preview.map(x=>[x.id,x]));$('#app').innerHTML=`<div class="wrap"><div class="bar"><h1 class="grow">Project Numbers v30</h1><button id="auth" class="btn">${S.connected?'Sign out':'Connect Autodesk'}</button></div><div id="err"></div><div class="card bar"><b>Hub</b><select id="hub" class="select grow">${S.hubs.map(h=>`<option value="${h.id}" ${h.id===S.hub?'selected':''}>${esc(h.name)}</option>`).join('')}</select><button id="load" class="btn">Load Projects</button></div><div class="notice"><b>Job number only.</b> Project names are shown only for identification and are never included in the update request.</div><div class="card"><div class="bar"><input id="search" class="input grow" placeholder="Search project name, job number, status or ID" value="${esc(S.search)}"><button id="all" class="btn soft">Select All Filtered</button><button id="clear" class="btn light">Deselect All</button><span class="badge">${S.selected.size} selected</span></div><div class="bar" style="margin-top:12px"><select id="operation" class="select"><option value="addPrefix">Add Prefix to Job Number</option><option value="removePrefix">Remove Prefix from Job Number</option><option value="addSuffix">Add Suffix to Job Number</option><option value="removeSuffix">Remove Suffix from Job Number</option><option value="set">Replace Full Job Number</option></select><input id="value" class="input grow" placeholder="Prefix, suffix, or complete job number"><button id="preview" class="btn soft">Preview</button><button id="apply" class="btn">Apply Job Number Changes</button><button id="export" class="btn light">Export Preview</button></div>${table(['Select','Project Name (unchanged)','Current Job Number','Proposed Job Number','Status','Platform','Validation'],visible().map(p=>{const x=pm.get(p.id);return[`<input class="pick" data-id="${p.id}" type="checkbox" ${S.selected.has(p.id)?'checked':''}>`,esc(p.name),esc(p.jobNumber),esc(x?.proposedJobNumber??''),esc(p.status),esc(p.platform),x?`<span class="${x.valid?'ok':'bad'}">${esc(x.validation)}</span>`:'']}))}</div></div>`;bind()}async function load(){let out=[],o=0,total=1;while(o<total){const d=await api(`projects-page&hubId=${encodeURIComponent(S.hub)}&offset=${o}`);out.push(...d.items);total=d.total;o=d.nextOffset}S.projects=out;render()}function preview(){const op=$('#operation').value,val=$('#value').value,res=[];for(const p of S.projects.filter(x=>S.selected.has(x.id))){let job=String(p.jobNumber||'');if(op==='addPrefix')job=val+job;if(op==='removePrefix'&&job.startsWith(val))job=job.slice(val.length);if(op==='addSuffix')job+=val;if(op==='removeSuffix'&&val&&job.endsWith(val))job=job.slice(0,-val.length);if(op==='set')job=val;res.push({...p,proposedJobNumber:job,valid:job.length<=100,validation:job.length<=100?'Ready, project name unchanged':'Job number exceeds 100 characters'})}S.preview=res;render()}async function apply(){const d=await api('project-job-numbers',{method:'POST',body:JSON.stringify({hubId:S.hub,projects:S.preview.filter(x=>x.valid)})});S.results=d.results;const ok=new Map(d.results.filter(x=>x.success).map(x=>[x.id,x]));S.projects=S.projects.map(p=>ok.has(p.id)?{...p,jobNumber:ok.get(p.id).proposedJobNumber}:p);S.preview=[];S.selected.clear();render();alert(`Completed. Success: ${d.results.filter(x=>x.success).length}, Failed: ${d.results.filter(x=>!x.success).length}`)}function exportX(){const w=XLSX.utils.book_new();XLSX.utils.book_append_sheet(w,XLSX.utils.json_to_sheet(S.preview.map(x=>({ProjectNameUnchanged:x.name,ProjectId:x.id,CurrentJobNumber:x.jobNumber,ProposedJobNumber:x.proposedJobNumber,Validation:x.validation}))), 'Job Number Preview');XLSX.writeFile(w,'BIM360_Job_Number_Preview.xlsx')}function bind(){$('#auth').onclick=async()=>S.connected?(await api('auth-logout',{method:'POST'}),location.reload()):(location.href=(await api('auth-login')).url);$('#hub').onchange=e=>S.hub=e.target.value;$('#load').onclick=load;$('#search').oninput=e=>{S.search=e.target.value;render()};document.querySelectorAll('.pick').forEach(x=>x.onchange=()=>x.checked?S.selected.add(x.dataset.id):S.selected.delete(x.dataset.id));$('#all').onclick=()=>{visible().forEach(p=>S.selected.add(p.id));render()};$('#clear').onclick=()=>{S.selected.clear();render()};$('#preview').onclick=preview;$('#apply').onclick=apply;$('#export').onclick=exportX}async function start(){if(location.pathname==='/callback'){await api('auth-callback&code='+encodeURIComponent(new URLSearchParams(location.search).get('code')||''));location.replace('/');return}const d=await api('auth-status');S.connected=d.authenticated;if(S.connected){const h=await api('hubs');S.hubs=h.hubs;S.hub=h.hubs[0]?.id||''}render()}start().catch(e=>{render();$('#err').innerHTML=`<div class="error">${esc(e.message)}</div>`});
